<template><section><PageHeading eyebrow="A PLACE FOR EVERY CONVERSATION" title="聊天记录" description="从一句话开始，找回你想要的那个瞬间。"><span class="pill"><UiIcon name="shield" :size="12"/>只读浏览</span><button class="btn" :disabled="!rawLogs.length||loading" @click="exportOpen=true"><UiIcon name="download" :size="14"/>导出记录</button></PageHeading><div class="chat-mobile-tabs segment-control"><button :class="{active:mobilePane==='list'}" @click="mobilePane='list'">会话列表</button><button :class="{active:mobilePane==='messages'}" @click="mobilePane='messages'">聊天记录</button></div><div class="chat-workspace"><aside class="chat-sidebar" :class="{'mobile-hidden':mobilePane!=='list'}" aria-label="选择会话"><div class="chat-sidebar-header"><h3>全部会话<span class="count">{{ workspace.sessions.length }}</span></h3><label class="search-field"><UiIcon name="search" :size="15"/><input v-model="sessionQuery" type="search" placeholder="搜索会话" aria-label="筛选左侧会话"/></label></div><div class="chat-side-list"><StatePanel v-if="workspace.loading" kind="loading"/><StatePanel v-else-if="workspace.errors.sessions" kind="error" title="会话读取失败" :description="workspace.errors.sessions" @retry="reloadWorkspace"/><template v-else><button v-for="session in shownSessions" :key="session.id" class="chat-side-item" :class="{selected:talkers.length===1&&talkers[0]===session.id}" :aria-pressed="talkers.length===1&&talkers[0]===session.id" @click="chooseSession(session)"><UiAvatar :name="session.name" :group="session.kind==='room'" small/><div><strong class="truncate">{{ session.name }}</strong><p class="truncate">{{ session.preview||'查看聊天记录' }}</p></div><time>{{ formatTime(session.lastMessageTime,true) }}</time></button></template><p v-if="!workspace.loading&&!shownSessions.length" class="scope-note">没有匹配的会话。也可以在筛选中直接输入对象 ID。</p></div></aside><div class="chat-main" :class="{'mobile-hidden':mobilePane!=='messages'}"><div class="chat-header"><UiAvatar :name="currentName" :group="currentSession?.kind==='room'"/><div class="chat-header-info"><h3 class="truncate">{{ currentName }}</h3><p class="truncate">{{ talkers.length?`${talkers.length} 个聊天对象 · 只读档案`:'跨会话搜索 · 不会发送消息' }}</p></div><button class="btn btn-ghost btn-square" aria-label="复制当前对象 ID" :disabled="!talkers.length" @click="copyText(talkers.join(','))"><UiIcon name="copy" :size="15"/></button><button class="btn btn-ghost btn-square" aria-label="刷新当前记录" :disabled="loading||!searched" @click="loadMessages(page)"><UiIcon name="refresh" :size="16"/></button></div><form class="chat-search" @submit.prevent="search"><label class="search-field"><UiIcon name="search" :size="16"/><input v-model="keyword" placeholder="搜索这段对话中的关键词…" aria-label="消息关键词" type="search"/></label><button class="btn btn-primary" type="submit" :disabled="loading">搜索</button><button class="btn" type="button" @click="openFilters"><UiIcon name="filter" :size="14"/>筛选<span v-if="filterCount" class="count">{{ filterCount }}</span></button></form><div v-if="startDate||endDate||extraKeywords.length" class="result-note">{{ startDate||'不限开始日期' }} — {{ endDate||'不限结束日期' }}<template v-if="extraKeywords.length"> · 本页{{ matchMode==='all'?'全部':'任意' }}匹配：{{ extraKeywords.join('、') }}</template><button class="text-button" style="margin-left:10px" @click="resetFilters">清除筛选</button></div><div v-if="extraKeywords.length" class="result-note">多关键词仅过滤当前后端返回页，不代表全量匹配结果。换页后继续筛选。</div><div ref="messageArea" class="chat-messages"><StatePanel v-if="loading" kind="loading"/><StatePanel v-else-if="error" kind="error" title="这段记录暂时无法读取" :description="error" @retry="loadMessages(page)"/><StatePanel v-else-if="!searched" title="从一段对话开始" description="选择左侧会话，或者输入一个关键词搜索所有记录。"/><StatePanel v-else-if="!visibleLogs.length" title="没有找到匹配的记录" description="尝试减少筛选条件；如果设置了本页筛选，也可继续翻页。"/><template v-else><template v-for="(message,index) in visibleLogs" :key="`${message.id||message.time}-${index}`"><div v-if="index===0||dateKey(message.time)!==dateKey(visibleLogs[index-1].time)" class="day-divider"><span>{{ dateKey(message.time)||'日期未知' }}</span></div><article class="message-row" :class="{self:message.isSelf}"><UiAvatar :name="message.senderName" small/><div class="message-column"><div class="message-meta"><strong>{{ message.senderName }}</strong><time>{{ formatTime(message.time,true) }}</time></div><div class="message-bubble"><MessageContent :content="message.content" :keywords="highlights"/></div></div></article></template></template></div><UiPager v-if="searched&&!error" :page="page" :size="pageSize" :total="total" :has-next="hasNext" :busy="loading" @change="loadMessages($event)"/><div class="chat-bottom-note"><span><UiIcon name="shield" :size="11"/>历史记录仅供查看，不支持发送</span><span v-if="searched">本页展示 {{ visibleLogs.length }} 条</span><span v-else>选择会话开始</span></div></div></div><UiDialog v-model="filtersOpen" title="缩小查找范围" eyebrow="FILTER YOUR CONVERSATIONS"><form id="chat-filter-form" class="filter-grid" @submit.prevent="applyFilters"><label class="field"><span>开始日期</span><input v-model="draft.start" type="date" :max="draft.end||undefined"/></label><label class="field"><span>结束日期</span><input v-model="draft.end" type="date" :min="draft.start||undefined"/></label><label class="field field-full"><span>聊天对象 ID（可多个）</span><textarea v-model="draft.talkers" rows="2" placeholder="ID 之间用逗号分隔；留空查询所有对象"/><p>也可以输入后端支持的备注名、昵称或群名称。</p></label><label class="field field-full"><span>本页追加关键词筛选</span><input v-model="draft.extra" placeholder="例如：设计, 交互"/><p>仅对当前加载页执行匹配。全量关键词查询请使用主搜索框。</p></label><label class="field"><span>本页匹配规则</span><select v-model="draft.mode"><option value="all">全部匹配（AND）</option><option value="any">任意匹配（OR）</option></select></label><label class="field"><span>每页加载数量</span><select v-model.number="draft.size"><option v-for="n in [20,50,100,200]" :key="n" :value="n">{{ n }} 条</option></select></label><p v-if="filterError" class="error-text field-full" role="alert">{{ filterError }}</p></form><template #footer><button class="btn" @click="filtersOpen=false">取消</button><button class="btn btn-primary" type="submit" form="chat-filter-form">应用筛选<UiIcon name="arrow" :size="14"/></button></template></UiDialog><UiDialog v-model="exportOpen" title="导出这段对话" eyebrow="TAKE YOUR ARCHIVE WITH YOU"><div class="filter-grid"><label class="field"><span>导出格式</span><select v-model="exportFormat"><option value="csv">CSV 表格</option><option value="json">JSON 数据</option><option value="text">纯文本</option></select></label><label class="field"><span>导出范围</span><select v-model="exportScope"><option value="page">当前可见页</option><option value="query">当前查询（最多 5,000 条）</option></select></label></div><div class="notice content-gap"><UiIcon name="info" :size="15"/><p>导出文件包含聊天内容，请妥善保存。“当前查询”从第 1 条开始读取，最多 5,000 条；追加关键词只对本次读取结果过滤，不保证穷尽所有匹配。</p></div><p v-if="exportError" class="error-text content-gap">{{ exportError }}</p><template #footer><button class="btn" @click="exportOpen=false">取消</button><button class="btn btn-primary" :disabled="exporting" @click="exportMessages"><UiIcon name="download" :size="14"/>{{ exporting?'正在读取…':'下载文件' }}</button></template></UiDialog></section></template>
<script>
import { ref,reactive,computed,watch,onMounted,onUnmounted,nextTick } from 'vue'
import { useRoute } from 'vue-router'
import api from '@/api'
import { workspace,loadWorkspace,copyText,notify } from '@/lib/workspace'
import { demoEnabled,clock } from '@/lib/demo'
import { dateKey,formatTime,toDate,csvString,download } from '@/lib/data'
import UiIcon from '@/components/ui/UiIcon.vue'
import UiAvatar from '@/components/ui/UiAvatar.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiPager from '@/components/ui/UiPager.vue'
import PageHeading from '@/components/ui/PageHeading.vue'
import StatePanel from '@/components/ui/StatePanel.vue'
import MessageContent from '@/components/MessageContent.vue'
export default {name:'ArchiveChatLog',components:{UiIcon,UiAvatar,UiDialog,UiPager,PageHeading,StatePanel,MessageContent},setup(){
 const route=useRoute(),sessionQuery=ref(''),keyword=ref(''),appliedKeyword=ref(''),talkers=ref([]),startDate=ref(''),endDate=ref(''),extraKeywords=ref([]),matchMode=ref('all'),page=ref(1),pageSize=ref(20),total=ref(null),rawLogs=ref([]),loading=ref(false),searched=ref(false),error=ref(''),filtersOpen=ref(false),exportOpen=ref(false),filterError=ref(''),exportError=ref(''),exporting=ref(false),exportFormat=ref('csv'),exportScope=ref('page'),mobilePane=ref('list'),messageArea=ref(null)
 const draft=reactive({start:'',end:'',talkers:'',extra:'',mode:'all',size:20});let sequence=0,alive=true
 const split=value=>String(value||'').split(/[,，\n]/).map(s=>s.trim()).filter(Boolean)
 const shownSessions=computed(()=>workspace.sessions.filter(s=>(s.name+' '+s.id).toLowerCase().includes(sessionQuery.value.toLowerCase())))
 const currentSession=computed(()=>talkers.value.length===1?workspace.sessions.find(s=>s.id===talkers.value[0]||s.name===talkers.value[0]):null)
 const currentName=computed(()=>currentSession.value?.name||(talkers.value.length===1?talkers.value[0]:talkers.value.length?`${talkers.value.length} 个聊天对象`:'全部聊天记录'))
 const matchLocal=logs=>logs.filter(log=>!extraKeywords.value.length||extraKeywords.value.map(w=>log.content.toLowerCase().includes(w.toLowerCase()))[matchMode.value==='all'?'every':'some'](Boolean))
 const visibleLogs=computed(()=>matchLocal(rawLogs.value).slice().sort((a,b)=>(toDate(a.time)?.getTime()||0)-(toDate(b.time)?.getTime()||0)))
 const highlights=computed(()=>[appliedKeyword.value,...extraKeywords.value].filter(Boolean)),hasNext=computed(()=>rawLogs.value.length>=pageSize.value),filterCount=computed(()=>Number(!!startDate.value||!!endDate.value)+Number(extraKeywords.value.length>0)+Number(talkers.value.length>1))
 const params=()=>({talker:talkers.value.join(','),keyword:appliedKeyword.value,time:startDate.value&&endDate.value?`${startDate.value}~${endDate.value}`:startDate.value||endDate.value||'',limit:pageSize.value})
 const loadMessages=async(target=1)=>{const current=++sequence;page.value=target;loading.value=true;searched.value=true;error.value='';mobilePane.value='messages';try{const response=await api.getChatLogs({...params(),offset:(target-1)*pageSize.value});if(!alive||current!==sequence)return;rawLogs.value=response.data;total.value=response.total;await nextTick();if(messageArea.value)messageArea.value.scrollTop=0}catch(e){if(alive&&current===sequence){error.value=e.message;rawLogs.value=[];total.value=null}}finally{if(alive&&current===sequence)loading.value=false}}
 const search=()=>{appliedKeyword.value=keyword.value.trim();return loadMessages(1)}
 const chooseSession=session=>{talkers.value=[session.id];appliedKeyword.value=keyword.value.trim();loadMessages(1)}
 const openFilters=()=>{Object.assign(draft,{start:startDate.value,end:endDate.value,talkers:talkers.value.join(', '),extra:extraKeywords.value.join(', '),mode:matchMode.value,size:pageSize.value});filterError.value='';filtersOpen.value=true}
 const applyFilters=()=>{if((draft.start&&!draft.end)||(!draft.start&&draft.end)){filterError.value='请同时填写开始和结束日期，或者全部留空。';return}if(draft.start&&draft.end&&draft.start>draft.end){filterError.value='开始日期不能晚于结束日期。';return}startDate.value=draft.start;endDate.value=draft.end;talkers.value=split(draft.talkers);extraKeywords.value=split(draft.extra);matchMode.value=draft.mode;pageSize.value=draft.size;filtersOpen.value=false;search()}
 const resetFilters=()=>{startDate.value='';endDate.value='';extraKeywords.value=[];search()}
 const applyRoute=()=>{const q=route.query||{};talkers.value=split(Array.isArray(q.talker)?q.talker.join(','):q.talker);keyword.value=String(q.keyword||'');if(q.talker||q.keyword)search()}
 watch(()=>[route.query?.talker,route.query?.keyword],applyRoute)
 const exportMessages=async()=>{exporting.value=true;exportError.value='';try{let rows=visibleLogs.value,limitReached=false;if(exportScope.value==='query'){const result=await api.getChatLogs({...params(),offset:0,limit:5000});limitReached=result.data.length>=5000;rows=matchLocal(result.data)}if(!rows.length){exportError.value='没有可导出的记录。';return}const filename=`chatlog-${exportScope.value==='query'?'查询样本':'当前页'}-${dateKey(clock())}`;if(exportFormat.value==='csv')download(csvString(rows,[{key:'senderName',label:'发送者'},{key:'senderId',label:'发送者ID'},{key:'time',label:'时间'},{key:'content',label:'内容'}]),filename+'.csv','text/csv;charset=utf-8');else if(exportFormat.value==='json')download(JSON.stringify(rows,null,2),filename+'.json','application/json');else download(rows.map(l=>`${l.senderName}(${l.senderId}) ${formatTime(l.time)}\n${l.content}`).join('\n\n'),filename+'.txt');exportOpen.value=false;notify(`已导出 ${rows.length} 条记录${limitReached?'；达到 5,000 条读取上限，结果可能不完整':''}`)}catch(e){exportError.value=e.message}finally{exporting.value=false}}
 onMounted(async()=>{applyRoute();await loadWorkspace();if(alive&&demoEnabled&&!searched.value&&workspace.sessions.length)chooseSession(workspace.sessions[0])});onUnmounted(()=>{alive=false;sequence++})
 return {workspace,sessionQuery,shownSessions,keyword,appliedKeyword,talkers,startDate,endDate,extraKeywords,matchMode,page,pageSize,total,rawLogs,visibleLogs,loading,searched,error,currentName,currentSession,highlights,hasNext,filterCount,filtersOpen,exportOpen,filterError,exportError,exporting,exportFormat,exportScope,mobilePane,messageArea,draft,dateKey,formatTime,copyText,chooseSession,loadMessages,search,openFilters,applyFilters,resetFilters,exportMessages,reloadWorkspace:()=>loadWorkspace(true)}
}}
</script>
